const DELL_RULE_SOURCES = [{"t": "XPS 4-digit code = 9 (premium XPS) + size digit (3=13.4\", 4=14.5\", 5=15.6\", 6=16.3\", 7=17\") + generation digit + variant digit. Generation d", "u": "https://www.dell.com/community/en/conversations/xps/dell-laptop-model-numbers-explanation/647f9494f4ccf8a8de6e22da"}, {"t": "XPS last digit: 0 = mainline Intel model; 5 = alternate/derivative model of the same generation: 9305 = cheaper 16:9 older-chassis Tiger Lak", "u": "https://www.pcworld.com/article/2337790/dell-launches-its-first-xps-laptop-with-a-snapdragon-x-elite-chip.html"}, {"t": "Inspiron (2020-2024): 1st digit = tier (3 = entry 3000, 5 = mainstream 5000, 7 = premium 7000 incl. 'Plus' and 2-in-1); 2nd digit = screen s", "u": "https://dl.dell.com/topicspdf/inspiron-14-5415-laptop_Users-Guide_en-us.pdf"}, {"t": "Inspiron 4th-digit exceptions: 1 = a second Intel platform or Qualcomm. Inspiron 15 3510 = Celeron/Pentium, 3511 = Core i3/i5/i7 (10th/11th ", "u": "https://katalog.atcomp.cz/katalog/D-N-3511-N2-512K/Inspiron-15-3000-3510-3511-3515-Tech-Spec-Sheet.pdf"}, {"t": "Inspiron 2024 Qualcomm variant: Inspiron 14 Plus 7441 (Snapdragon X Plus, 54 Wh, 1.4 kg, $999.99) vs 7440 (Intel Core Ultra H, 64 Wh, 1.6 kg", "u": "https://www.windowscentral.com/hardware/laptops/dell/dell-inspiron-14-plus-7440-review"}, {"t": "Inspiron 7000-tier codes are shared by the 'Plus' clamshell and the 2-in-1 convertible of the same size/year (e.g. Inspiron 14 Plus 7420 vs ", "u": "https://www.notebookcheck.net/Mini-LED-on-a-16-inch-convertible-Dell-Inspiron-16-7640-2-in-1-review.862070.0.html"}, {"t": "Since 2021 Dell dropped the 4-digit number from Inspiron marketing names ('Inspiron 14', 'Inspiron 16 Plus'); the code still appears on the ", "u": "https://www.tomshardware.com/news/dell-inspiron-16-plus-price-specs-11th-gen-intel"}, {"t": "Pre-2020 Inspiron scheme: 1st digit series, 2nd digit screen size, 3rd digit = last digit of year (e.g. 5378 = 13\" 2017, 5593 = 15\" 2019), 4", "u": "https://en.tab-tv.com/?p=14313"}, {"t": "Dell G-series: G15 = 15.6\", G16 = 16\". Code = 5 (G15 tier) or 7 (G16 tier) + size digit + year digit (1=2021, 2=2022, 3=2023) + platform: 0 ", "u": "https://www.notebookcheck.net/Dell-G15-refreshed-with-an-NVIDIA-GeForce-RTX-3060-and-a-choice-between-AMD-Ryzen-5000-or-Intel-Comet-Lake-H-processors.531226.0.html"}, {"t": "G15 5521 SE exists alongside 5520 (12th gen Intel, launched 2022).", "u": "https://www.pressreader.com/india/ht-city/20220520/281655373682477"}, {"t": "January 2025 rename (CES 2025): families Dell (consumer) / Dell Pro (business) / Dell Pro Max (workstation), each with tiers Base (no suffix", "u": "https://tech.yahoo.com/computing/articles/decode-dells-2025-pc-rebrand-213355852.html"}, {"t": "Dell 16 Plus (DB16250) is the direct successor of the Inspiron 16 Plus series.", "u": "https://www.notebookcheck.net/Dell-16-Plus-laptop-review-A-wave-goodbye-to-the-Inspiron-series.1028836.0.html"}];
